using System.Numerics;

namespace NDSharp.Tests;

/// <summary>Complex sorting and N-d diagonal/trace against numpy (cases generated by tools/oracle/gen_sortdiag_tests.py).</summary>
public class SortDiagTests
{
    static DType Dt(string name) => Enum.Parse<DType>(name);

    static NDArray Build(SortDiagCases.Input i)
    {
        var dt = Dt(i.DType);
        NDArray a = dt.IsComplex()
            ? new NDArray(DType.Complex128, i.Re.Zip(i.Im, (r, m) => new Complex(r, m)).ToArray(), i.Shape)
            : new NDArray(DType.Float64, i.Re, i.Shape);
        return a.DType == dt ? a : a.AsType(dt);
    }

    static (double[] re, double[] im) Parts(NDArray a)
    {
        if (a.DType.IsComplex())
        {
            var z = a.AsType(DType.Complex128).ToArray<Complex>();
            return (z.Select(c => c.Real).ToArray(), z.Select(c => c.Imaginary).ToArray());
        }
        return (a.AsType(DType.Float64).ToArray<double>(), Array.Empty<double>());
    }

    static bool Same(double x, double y) => x == y || (double.IsNaN(x) && double.IsNaN(y));

    static NDArray Run(string op, NDArray a)
    {
        var (name, args) = op.Split(':') is { Length: 2 } p ? (p[0], p[1]) : (op, "");
        int[] n() => args.Split(',').Select(int.Parse).ToArray();
        switch (name)
        {
            case "sort": return args == "none" ? np.Sort(a, null) : np.Sort(a, int.Parse(args));
            case "argsort": return np.ArgSort(a, int.Parse(args));
            case "sort_complex": return np.SortComplex(a);
            case "diagonal": { var v = n(); return np.Diagonal(a, v[0], v[1], v[2]); }
            case "trace": { var v = n(); return np.Trace(a, v[0], v[1], v[2]); }
            case "isnan": return np.IsNan(a);
            case "isinf": return np.IsInf(a);
            case "isfinite": return np.IsFinite(a);
            case "unique_values": return np.Unique(a, true, true, true).Values;
            case "unique_index": return np.Unique(a, true, true, true).Index!;
            case "unique_inverse": return np.Unique(a, true, true, true).Inverse!;
            case "unique_counts": return np.Unique(a, true, true, true).Counts!;
        }
        throw new InvalidOperationException(op);
    }

    public static IEnumerable<object[]> Cases() => SortDiagCases.All.Select(c => new object[] { c.Label });

    [Theory]
    [MemberData(nameof(Cases))]
    public void MatchesNumpy(string label)
    {
        var c = SortDiagCases.All.Single(x => x.Label == label);
        var input = Build(SortDiagCases.Inputs.Single(i => i.Name == c.Input));
        var got = Run(c.Op, input);

        Assert.Equal(c.Shape, got.Shape);
        Assert.Equal(Dt(c.DType), got.DType);
        var (re, im) = Parts(got);
        Assert.Equal(c.Re.Length, re.Length);
        for (int i = 0; i < re.Length; i++)
        {
            Assert.True(Same(c.Re[i], re[i]), $"{label}: element {i} real part expected {c.Re[i]}, got {re[i]}");
            if (c.Im.Length > 0) Assert.True(Same(c.Im[i], im[i]), $"{label}: element {i} imaginary part expected {c.Im[i]}, got {im[i]}");
        }
    }

    [Fact]
    public void SortingDoesNotTouchTheInput()
    {
        var a = new NDArray(DType.Complex128, new[] { new Complex(2, 1), new Complex(1, 5), new Complex(1, -1) }, new[] { 3 });
        var copy = a.Copy();
        np.Sort(a);
        Assert.Equal(copy.ToArray<Complex>(), a.ToArray<Complex>());
    }

    [Fact]
    public void DiagonalIsAViewOnTheSameBuffer()
    {
        var a = np.Reshape(np.Arange(0L, 24L), new[] { 2, 3, 4 });
        var d = np.Diagonal(a, 0, 1, 2);
        Assert.Equal(new[] { 2, 3 }, d.Shape);
        Assert.Same(a.Buffer, d.Buffer);
    }

    [Fact]
    public void DiagonalRejectsBadAxes()
    {
        var a = np.Zeros(new[] { 2, 3, 4 });
        Assert.Throws<NDValueException>(() => np.Diagonal(a, 0, 1, 1));
        Assert.Throws<NDAxisException>(() => np.Diagonal(a, 0, 0, 3));
        Assert.Throws<NDValueException>(() => np.Diagonal(np.Zeros(new[] { 3 })));
        Assert.Throws<NDValueException>(() => np.Trace(np.Zeros(new[] { 3 })));
    }

    [Fact]
    public void TraceHonoursDtype()
    {
        var a = NDArray.FromArray(new byte[] { 200, 0, 0, 100 }, 2, 2);
        Assert.Equal(300.0, Convert.ToDouble(np.Trace(a, 0, 0, 1, DType.Float64).GetAt(0)));
    }

    [Fact]
    public void TwoDimensionalDefaultsAreUnchanged()
    {
        var a = NDArray.FromMultiDim(new double[,] { { 1, 2, 3 }, { 4, 5, 6 }, { 7, 8, 9 } });
        Assert.Equal(15.0, Convert.ToDouble(np.Trace(a).GetAt(0)));
        Assert.Equal(new double[] { 2, 6 }, np.Diagonal(a, 1).ToArray<double>());
        Assert.Equal(new double[] { 4, 8 }, np.Diagonal(a, -1).ToArray<double>());
    }
}


